#!/usr/bin/env node
// Generates every derived file from registry.json.
// Usage: node tools/build.mjs          write generated files
//        node tools/build.mjs --check  fail if anything is stale or inconsistent
import { readFileSync, writeFileSync, existsSync, readdirSync, statSync, mkdirSync } from "node:fs";
import { join, dirname, basename, extname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");
const reg = JSON.parse(readFileSync(join(root, "registry.json"), "utf8"));
const langs = [...reg.languages].sort((a, b) => a.name.localeCompare(b.name, "en", { sensitivity: "base" }));
const errors = [];
const HEADER = "Generated by tools/build.mjs from registry.json. Do not edit by hand.";

// ---------- helpers ----------
const q = (s) => JSON.stringify(s);
const xml = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const walk = (dir) => readdirSync(dir).flatMap((f) => {
  const p = join(dir, f);
  return statSync(p).isDirectory() ? walk(p) : [p];
});

// ---------- generators ----------
function linguistLanguages() {
  const out = [`# ${HEADER}`, "# Paste into lib/linguist/languages.yml of github-linguist (keep alphabetical order).", "# language_id values are assigned by script/update-ids in the Linguist tree."];
  for (const l of langs) {
    out.push(`${l.name.includes(".") || l.name.includes(" ") ? l.name : l.name}:`);
    out.push(`  type: ${l.type}`);
    out.push(`  color: ${q(l.color)}`);
    if (l.aliases.length) { out.push("  aliases:"); for (const a of l.aliases) out.push(`  - ${a}`); }
    out.push("  extensions:"); for (const e of l.extensions) out.push(`  - ${q(e)}`);
    if (l.filenames.length) { out.push("  filenames:"); for (const f of l.filenames) out.push(`  - ${f}`); }
    if (l.interpreters.length) { out.push("  interpreters:"); for (const i of l.interpreters) out.push(`  - ${i}`); }
    out.push(`  tm_scope: ${l.scope}`);
    out.push(`  ace_mode: ${l.ace_mode}`);
    if (l.wrap) out.push("  wrap: true");
  }
  return out.join("\n") + "\n";
}

function linguistHeuristics() {
  const inc = langs.find((l) => l.extensions.includes(".inc"));
  return [
    `# ${HEADER}`,
    "# Put this rule FIRST inside the existing `- extensions: ['.inc']` block of lib/linguist/heuristics.yml.",
    "# The signature line is unique, so it cannot steal PHP, Pascal, POV-Ray or assembly includes.",
    `  - language: ${inc.name}`,
    `    pattern: '${inc.signature}'`,
  ].join("\n") + "\n";
}

function mimeXml() {
  const out = ['<?xml version="1.0" encoding="UTF-8"?>', `<!-- ${HEADER} -->`, '<mime-info xmlns="http://www.freedesktop.org/standards/shared-mime-info">'];
  for (const l of langs) {
    out.push(`  <mime-type type="${l.mime}">`);
    out.push(`    <comment>${xml(l.name)} ${l.type === "prose" ? "document" : l.type === "data" ? "file" : "source code"}</comment>`);
    out.push(`    <sub-class-of type="text/plain"/>`);
    for (const e of l.extensions) out.push(`    <glob pattern="*${e}"${e === ".inc" ? ' weight="10"' : ""}/>`);
    for (const f of l.filenames) out.push(`    <glob pattern="${xml(f)}" case-sensitive="true"/>`);
    out.push(`    <magic priority="60">`);
    out.push(`      <match type="string" offset="0" value="${xml(magicPrefix(l))}"/>`);
    out.push(`    </magic>`);
    out.push(`  </mime-type>`);
  }
  out.push("</mime-info>");
  return out.join("\n") + "\n";
}

// Literal prefix of the signature, used by file(1) and shared-mime-info magic.
function magicPrefix(l) {
  return { "Machen": "#! machen", "Markdebil": "+++ markdebil", "R3000": ";; R3000", "Szajs Script": "#!/usr/bin/env szajs", "Szmelc.inc": "%szmelc.inc", "Vibe-C": "//! vibe-c" }[l.name];
}

function magicFile() {
  const out = [`# ${HEADER}`, "# Use: file -m integrations/magic/szmelc.magic <file>  (or append to /etc/magic)"];
  for (const l of langs) {
    const p = magicPrefix(l).replace(/ /g, "\\ ");
    out.push(`0\tstring\t${p}\t${l.name} ${l.type === "prose" ? "document" : l.type === "data" ? "file" : "source"}, text`);
    out.push(`!:mime\t${l.mime}`);
  }
  return out.join("\n") + "\n";
}

function vimFtdetect() {
  const out = [`" ${HEADER}`];
  for (const l of langs) {
    const globs = [...l.extensions.filter((e) => e !== ".inc").map((e) => `*${e}`), ...l.filenames].join(",");
    out.push(`autocmd BufRead,BufNewFile ${globs} setfiletype ${l.slug.replace(/-/g, "_")}`);
  }
  out.push(`" .inc is shared with many languages: only claim it when the signature is present.`);
  out.push(`autocmd BufRead,BufNewFile *.inc if getline(1) =~# '^%szmelc\\.inc\\>' | setlocal filetype=szmelc_inc | endif`);
  out.push(`autocmd BufRead * if getline(1) =~# '^#!.*\\<szajs\\>' | setfiletype szajs_script | endif`);
  out.push(`autocmd BufRead * if getline(1) =~# '^#!.*\\<\\(r3k\\|rozkurwator\\)\\>' | setfiletype r3000 | endif`);
  return out.join("\n") + "\n";
}

function vimSyntax(l) {
  const ft = l.slug.replace(/-/g, "_");
  const out = [`" Vim syntax for ${l.name}. ${HEADER}`, `if exists("b:current_syntax") | finish | endif`];
  if (l.keywords.length) out.push(`syntax keyword ${ft}Keyword ${l.keywords.join(" ")}`);
  if (l.constants.length) out.push(`syntax keyword ${ft}Constant ${l.constants.join(" ")}`);
  out.push(`syntax region ${ft}String start=+"+ skip=+\\\\.+ end=+"+`);
  out.push(`syntax match ${ft}Number "\\<\\d\\+\\(\\.\\d\\+\\)*\\>"`);
  if (l.comment === "%%") out.push(`syntax region ${ft}Comment start="%%" end="%%"`);
  else out.push(`syntax match ${ft}Comment "${l.comment.replace(/\//g, "\\/")}.*$"`);
  out.push(`syntax match ${ft}Signature "\\%1l${vimEsc(magicPrefix(l))}.*$"`);
  out.push(`highlight default link ${ft}Keyword Keyword`, `highlight default link ${ft}Constant Constant`, `highlight default link ${ft}String String`,
    `highlight default link ${ft}Number Number`, `highlight default link ${ft}Comment Comment`, `highlight default link ${ft}Signature PreProc`);
  out.push(`let b:current_syntax = "${ft}"`);
  return out.join("\n") + "\n";
}
const vimEsc = (s) => s.replace(/[\\/.*$^~[\]]/g, (c) => "\\" + c).replace(/\+/g, "+");

function vscodePackage() {
  return JSON.stringify({
    name: "szmelc-languages",
    displayName: "Szmelc Languages",
    description: "Syntax highlighting for Vibe-C, Szajs Script, Szmelc.inc, Markdebil, Machen and R3000 (Rozkurwator 3000).",
    version: reg.version,
    publisher: "szmelc-inc",
    license: "MIT",
    repository: { type: "git", url: "https://github.com/Szmelc-INC/Szmelc-Languages" },
    engines: { vscode: "^1.80.0" },
    categories: ["Programming Languages"],
    contributes: {
      languages: langs.map((l) => ({
        id: l.slug,
        aliases: [l.name, ...l.aliases],
        extensions: l.extensions.filter((e) => e !== ".inc"),
        ...(l.filenames.length ? { filenames: l.filenames } : {}),
        ...(l.signature ? { firstLine: l.signature } : {}),
        configuration: `./languages/${l.slug}.json`,
      })),
      grammars: langs.map((l) => ({ language: l.slug, scopeName: l.scope, path: `./grammars/${l.slug}.tmLanguage.json` })),
    },
  }, null, 2) + "\n";
}

function gitattributes() {
  const out = [`# ${HEADER}`,
    "# Interim mapping: until Linguist knows these languages, count them as the nearest existing one",
    "# so they show up in the GitHub language bar. Copy into a repo's .gitattributes.",
    "# linguist-language can only name languages Linguist already ships."];
  for (const l of langs) {
    out.push(`# ${l.name} -> ${l.interim}`);
    for (const e of l.extensions.filter((e) => e !== ".inc")) out.push(`*${e} linguist-language=${l.interim}${l.type === "prose" ? " linguist-detectable" : ""}`);
    for (const f of l.filenames) out.push(`${f} linguist-language=${l.interim}`);
  }
  return out.join("\n") + "\n";
}

// ---------- outputs ----------
const outputs = {
  "linguist/languages.yml": linguistLanguages(),
  "linguist/heuristics.yml": linguistHeuristics(),
  "integrations/mime/szmelc-languages.xml": mimeXml(),
  "integrations/magic/szmelc.magic": magicFile(),
  "integrations/vim/ftdetect/szmelc.vim": vimFtdetect(),
  "integrations/vscode/package.json": vscodePackage(),
  "integrations/gitattributes/interim.gitattributes": gitattributes(),
};
for (const l of langs) {
  outputs[`integrations/vim/syntax/${l.slug.replace(/-/g, "_")}.vim`] = vimSyntax(l);
  outputs[`integrations/vscode/grammars/${l.slug}.tmLanguage.json`] = readFileSync(join(root, "grammars", `${l.slug}.tmLanguage.json`), "utf8");
  const block = { "Vibe-C": ["/*", "*/"], "Szajs Script": ["#[", "]#"], "Markdebil": ["%%", "%%"] }[l.name];
  outputs[`integrations/vscode/languages/${l.slug}.json`] = JSON.stringify({
    comments: { ...(l.comment !== "%%" ? { lineComment: l.comment } : {}), ...(block ? { blockComment: block } : {}) },
    brackets: [["{", "}"], ["[", "]"], ["(", ")"]],
    autoClosingPairs: [{ open: "{", close: "}" }, { open: "[", close: "]" }, { open: "(", close: ")" }, { open: "\"", close: "\"", notIn: ["string"] }],
    surroundingPairs: [["{", "}"], ["[", "]"], ["(", ")"], ["\"", "\""]],
  }, null, 2) + "\n";
}

// ---------- consistency checks ----------
const seenExt = new Map();
for (const l of langs) {
  if (!/^#[0-9a-f]{6}$/i.test(l.color)) errors.push(`${l.name}: bad color ${l.color}`);
  for (const e of l.extensions) {
    if (seenExt.has(e)) errors.push(`${e} claimed by ${seenExt.get(e)} and ${l.name}`);
    seenExt.set(e, l.name);
  }
  const g = join(root, "grammars", `${l.slug}.tmLanguage.json`);
  if (!existsSync(g)) { errors.push(`${l.name}: missing grammar ${g}`); continue; }
  const gram = JSON.parse(readFileSync(g, "utf8"));
  if (gram.scopeName !== l.scope) errors.push(`${l.name}: grammar scope ${gram.scopeName} != ${l.scope}`);
  if (gram.name !== l.name) errors.push(`${l.name}: grammar name ${gram.name} != ${l.name}`);
  const sdir = join(root, "samples", l.name);
  if (!existsSync(sdir)) { errors.push(`${l.name}: missing samples/${l.name}`); continue; }
  const files = walk(sdir);
  for (const e of l.extensions) if (!files.some((f) => extname(f) === e)) errors.push(`${l.name}: no sample for ${e}`);
  const groups = [...new Set(l.filenames.map((f) => f.toLowerCase()))];
  for (const g of groups) if (!files.some((p) => basename(p).toLowerCase() === g)) errors.push(`${l.name}: no sample for filename ${g}`);
  const sig = new RegExp(l.signature, "m");
  for (const f of files) {
    if (extname(f) === ".inc" && !sig.test(readFileSync(f, "utf8").split("\n")[0])) errors.push(`${f}: .inc sample must start with the signature`);
  }
  if (!existsSync(join(root, "docs", `${l.slug}.md`))) errors.push(`${l.name}: missing docs/${l.slug}.md`);
}

for (const [rel, content] of Object.entries(outputs)) {
  const p = join(root, rel);
  if (check) {
    if (!existsSync(p) || readFileSync(p, "utf8") !== content) errors.push(`stale: ${rel} (run node tools/build.mjs)`);
  } else {
    mkdirSync(dirname(p), { recursive: true });
    writeFileSync(p, content);
  }
}

if (errors.length) { console.error(errors.map((e) => "✗ " + e).join("\n")); process.exit(1); }
console.log(check ? `✓ ${langs.length} languages consistent, ${Object.keys(outputs).length} generated files up to date` : `✓ wrote ${Object.keys(outputs).length} files`);
